{"command":"cat > /tmp/chronotest/src/main.rs <<'RS'
use chrono::{NaiveDateTime, Timelike, Duration};
fn fmt(dt: NaiveDateTime)->String{ dt.format("%Y-%m-%d %H:%M").to_string() }
fn main(){
 for s in ["2020-01-01 09:00:00","2020-01-01 09:00:29","2020-01-01 09:00:30","2020-01-01 09:00:59","2020-01-01 09:00:60","2020-01-01 23:59:59","2020-01-01 23:59:60"] {
   let dt=NaiveDateTime::parse_from_str(s,"%Y-%m-%d %H:%M:%S").unwrap();
   // impl A: if sec>=30 add minute, then with_second 0
   let a = {
     let mut r=dt;
     if r.second()>=30 { r=r+Duration::minutes(1); }
     r.with_second(0).unwrap().with_nanosecond(0).unwrap()
   };
   // impl B: add 30 sec then truncate sec/nano via with
   let b = { let r=dt+Duration::seconds(30); r.with_second(0).unwrap().with_nanosecond(0).unwrap() };
   // impl C: timestamp rounding: (ts+30)/60*60
   let c = { let ts=dt.and_utc().timestamp(); let rounded=((ts+30).div_euclid(60))*60; NaiveDateTime::from_timestamp_opt(rounded,0).unwrap_or(dt) };
   // impl D: second() but with nanosecond consideration? if sec+ nano/1e9 >=30
   // impl E: format with something?
   println!("{s} orig={} fmtHM={} sec={} nano={} A={} B={} C={}", dt, fmt(dt), dt.second(), dt.nanosecond(), fmt(a), fmt(b), fmt(c));
 }
}
RS
cargo run --offline --quiet --manifest-path /tmp/chronotest/Cargo.toml 2>&1"}

