#!/usr/bin/env python3
# Original reimplementation of the bartib 1.1.0 command line time tracker,
# written from observed behaviour of the reference executable.
import os
import re
import subprocess
import sys
import time

VERSION = "1.1.0"
NBSP = "\u00a0"
WARNING_SECOND_PRECISION = (
