# ---------------------------------------------------------------------------
# Calendar / naive date time (proleptic Gregorian, supports year <= 0)
# ---------------------------------------------------------------------------

def is_leap_year(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

_MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

def days_in_month(y, m):
    if m == 2:
        return 29 if is_leap_year(y) else 28
    return _MONTH_DAYS[m - 1]

def days_from_civil(y, m, d):
    # Howard Hinnant's algorithm; returns days since 1970-01-01.
    yy = y - (1 if m <= 2 else 0)
    era = yy // 400  # Python // is floor division
    yoe = yy - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468

def civil_from_days(z):
    zz = z + 719468
    era = zz // 146097
    doe = zz - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + (3 if mp < 10 else -9)
    if m <= 2:
        y += 1
    return y, m, d

def format_year(y):
    if y < 0:
        return "-%04d" % abs(y)
    return "%04d" % y

class NaiveDT:
    __slots__ = ("days", "secs", "nanos")
    # days: civil days since epoch for the *displayed* date
    # secs: seconds within the displayed day (for a leap second this is
    #       minute*60+59 and nanos == 1_000_000_000, mirroring chrono)
    # nanos: 0 normally, 1_000_000_000 for a leap second

    def __init__(self, days, secs, nanos=0):
        self.days = days
        self.secs = secs
        self.nanos = nanos

    @classmethod
    def from_ymd_hms(cls, y, mo, d, h, mi, s=0):
        days = days_from_civil(y, mo, d)
        if s == 60:
            return cls(days, h * 3600 + mi * 60 + 59, 1000000000)
        return cls(days, h * 3600 + mi * 60 + s, 0)

    @classmethod
    def from_total_seconds(cls, total):
        days = total // 86400
        secs = total - days * 86400
        return cls(days, secs, 0)

    def ymd(self):
        return civil_from_days(self.days)

    def hms(self):
        h = self.secs // 3600
        mi = (self.secs // 60) % 60
        s = self.secs % 60
        return h, mi, s

    def format_date(self):
        y, m, d = self.ymd()
        return f"{format_year(y)}-{m:02d}-{d:02d}"

    def format_time(self):
        h, mi, _s = self.hms()
        return f"{h:02d}:{mi:02d}"

    def format_datetime(self):
        return f"{self.format_date()} {self.format_time()}"

    def sort_key(self):
        return (self.days, self.secs, self.nanos)

    def total_nanos(self):
        return ((self.days * 86400 + self.secs) * 1000000000) + self.nanos

    def timestamp_seconds(self):
        # chrono NaiveDateTime::timestamp(): seconds of the displayed
        # date/time, ignoring the leap-second nanosecond overflow.
        return self.day * 86400 + self.secs

    def date_days(self):
        return self.days

    def add_seconds(self, delta):
        total = self.timestamp_seconds() + delta
        # If this was a leap second, timestamp_seconds() is one second
        # before the true instant; adding via the true instant instead
        # is indistinguishable for the minute-precision uses here
        # except for the leap case, which callers do not add to.
        return NaiveDT.from_total_seconds(total)

def dt_from_ymd_hm(y, mo, d, h, mi):
    return NaiveDT.from_ymd_hms(y, mo, d, h, mi, 0)

def now_dt():
    lt = time.localtime()
    return NaiveDT.from_ymd_hms(lt.tm_year, lt.tm_mon, lt.tm_mday, lt.tm_hour, lt.tm_min, 0)

def today_days():
    lt = time.localtime()
    return days_from_civil(lt.tm_year, lt.tm_mon, lt.tm_mday)

def duration_minutes_between(start, end):
    # chrono Duration::num_minutes(): truncation toward zero
    total_nanos = end.total_nanos() - start.total_nanos()
    denom = 60 * 1000000000
    if total_nanos >= 0:
        return total_nanos // denom
    return -((-total_nanos) // denom)

def duration_total_minutes_from_nanos(total_nanos):
    denom = 60 * 1000000000
    if total_nanos >= 0:
        return total_nanos // denom
    return -((-total_nanos) // denom)

def format_duration_minutes(total_minutes):
    if total_minutes >= 60:
        hours = total_minutes // 60
        mins = total_minutes - hours * 60
        return f"{hours}h {mins:02d}m"
    if total_minutes > 0:
        return f"{total_minutes:02d}m"
    return "<1m"

def format_duration_nanos(total_nanos):
    return format_duration_minutes(duration_total_minutes_from_nanos(total_nanos))

# ---------------------------------------------------------------------------
# chrono-like parsing
# ---------------------------------------------------------------------------

class ChronoParseError(Exception):
    def __init__(self, kind):
        super().__init__(kind)
        self.kind = kind

    def display(self):
        return {
            "too_short": "premature end of input",
            "empty": "premature end of input",
            "invalid": "input contains invalid characters",
            "too_long": "trailing input",
            "out_of_range": "input is out of range",
            "impossible": "no possible date and time matching input",
        }.get(self.kind, self.kind)

def _parse_chrono(s, fmt):
    """Parse s according to a chrono strftime-like fmt.
    Returns dict of fields.  Raises ChronoParseError."""
    fields = {}
    si = 0
    fi = 0
    slen = len(s)
    flen = len(fmt)

    def skip_ws():
        nonlocal si
        while si < slen and s[si].isspace():
            si += 1

    while fi < flen:
        fc = fmt[fi]
        if fc == "%":
            if fi + 1 >= flen:
                raise ChronoParseError("invalid")
            directive = fmt[fi + 1]
            fi += 2
            # numeric fields skip leading whitespace in chrono
            skip_ws()
            if si >= slen:
                raise ChronoParseError("too_short")
            if directive == "Y":
                sign = 1
                if si < slen and s[si] in "+-":
                    if s[si] == "-":
                        sign = -1
                    si += 1
                start = si
                while si < slen and si - start < 4 and s[si].isdigit() and s[si] in "0123456789":
                    si += 1
                if si == start:
                    raise ChronoParseError("invalid")
                fields["year"] = sign * int(s[start:si])
            elif directive in "mdHMS":
                start = si
                while si < slen and si - start < 2 and s[si] in "0123456789":
                    si += 1
                if si == start:
                    raise ChronoParseError("invalid")
                val = int(s[start:si])
                if directive == "m":
                    if val < 1 or val > 12:
                        raise ChronoParseError("out_of_range")
                    fields["month"] = val
                elif directive == "d":
                    if val < 1 or val > 31:
                        raise ChronoParseError("out_of_range")
                    fields["day"] = val
                elif directive == "H":
                    if val > 23:
                        raise ChronoParseError("out_of_range")
                    fields["hour"] = val
                elif directive == "M":
                    if val > 59:
                        raise ChronoParseError("out_of_range")
                    fields["minute"] = val
                elif directive == "S":
                    if val > 60:
                        raise ChronoParseError("out_of_range")
                    fields["second"] = val
            else:
                raise ChronoParseError("invalid")
        elif fc == " ":
            # a space in the format matches any amount of whitespace
            skip_ws()
            fi += 1
        else:
            if si >= slen:
                raise ChronoParseError("too_short")
            if s[si] != fc:
                raise ChronoParseError("invalid")
            si += 1
            fi += 1
    if si < slen:
        raise ChronoParseError("too_long")
    return fields

def chrono_parse_datetime(s, with_seconds):
    fmt = "%Y-%m-%d %H:%M:%S" if with_seconds else "%Y-%m-%d %H:%M"
    f = _parse_chrono(s, fmt)
    # combined date validation happens after trailing-input checks
    y, mo, d = f["year"], f["month"], f["day"]
    if d > days_in_month(y, mo):
        raise ChronoParseError("out_of_range")
    sec = f.get("second", 0)
    return NaiveDT.from_ymd_hms(y, mo, d, f["hour"], f["minute"], sec), sec

def chrono_parse_date(s):
    f = _parse_chrono(s, "%Y-%m-%d")
    y, mo, d = f["year"], f["month"], f["day"]
    if d > days_in_month(y, mo):
        raise ChronoParseError("out_of_range")
    return days_from_civil(y, mo, d)

def chrono_parse_time(s):
    f = _parse_chrono(s, "%H:%M")
    return f["hour"], f["minute"]

# ---------------------------------------------------------------------------
# Activity
# ---------------------------------------------------------------------------

class Activity:
    __slots__ = ("start", "end", "project", "description", "line_number")
    def __init__(self, start, end, project, description, line_number=0):
        self.start = start
        self.end = end
        self.project = project
        self.description = description
        self.line_number = line_number

    def duration_nanos(self, now):
        end = self.end if self.end is not None else now
        return end.total_nanos() - self.start.total_nanos()

    def get_duration_string(self, now):
        return format_duration_nanos(self.duration_nanos(now))

def escape_field(text):
    return text.replace("\\", "\\\\").replace("|", "\\|")

def activity_to_line(act):
    if act.end is None:
        return f"{act.start.format_datetime()} | {escape_field(act.project)} | {escape_field(act.description)}"
    return f"{act.start.format_datetime()} - {act.end.format_datetime()} | {escape_field(act.project)} | {escape_field(act.description)}"

class ActivityParseError(Exception):
    def __init__(self, kind):
        # kind: 'activity' or 'datetime'
        super().__init__(kind)
        self.kind = kind
    def message(self):
        if self.kind == "activity":
            return "could not parse activity"
        return "could not parse date or time of activity"

def split_escaped(line):
    """Split a line on unescaped '|', removing escape backslashes.
    Behaves like a split_terminator: a trailing delimiter does not
    produce a final empty token."""
    tokens = []
    cur = []
    i = 0
    n = len(line)
    ended_with_delimiter = False
    if n == 0:
        return []
    while i < n:
        c = line[i]
        if c == "\\":
            if i + 1 < n:
                cur.append(line[i + 1])
                i += 2
            else:
                i += 1
            ended_with_delimiter = False
        elif c == "|":
            tokens.append("".join(cur))
            cur = []
            i += 1
            ended_with_delimiter = True
        else:
            cur.append(c)
            i += 1
            ended_with_delimiter = False
    if not ended_with_delimiter:
        tokens.append("".join(cur))
    return tokens

def _round_to_minute(dt, original_second):
    if original_second == 60:
        # leap second: chrono keeps the displayed minute
        return dt
    h, mi, _s = dt.hms()
    # rebuild at minute precision, rounding half up
    base_days = dt.days
    if original_second >= 30:
        total = base_days * 1440 + h * 60 + mi + 1
        days = total // 1440
        rem = total - days * 1440
        return NaiveDT(days, rem * 60, 0)
    return NaiveDT(base_days, (h * 60 + mi) * 60, 0)

def parse_activity_datetime(s, emit_second_warning=True):
    try:
        dt, _sec = chrono_parse_datetime(s, False)
        return dt
    except ChronoParseError:
        pass
    try:
        dt, sec = chrono_parse_datetime(s, True)
    except ChronoParseError:
        raise ActivityParseError("datetime")
    if emit_second_warning:
        err_write(WARNING_SECOND_PRECISION)
    return _round_to_minute(dt, sec)

def parse_activity(line, line_number=0, emit_second_warning=True):
    tokens = split_escaped(line)
    if len(tokens) < 2:
        raise ActivityParseError("activity")
    time_token = tokens[0].strip()
    project = tokens[1].strip()
    description = tokens[2].strip() if len(tokens) > 2 else ""
    parts = time_token.split(" - ")
    start = parse_activity_datetime(parts[0].strip(), emit_second_warning)
    end = None
    if len(parts) > 1:
        end = parse_activity_datetime(parts[1].strip(), emit_second_warning)
    return Activity(start, end, project, description, line_number)

# ---------------------------------------------------------------------------
# File handling
# ---------------------------------------------------------------------------

def read_lines(path):
    """Read lines the way Rust's BufRead::lines() consumer in the
    original does: opening errors are reported, but iteration stops
    at the first I/O / UTF-8 error."""
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError as e:
        raise BartibError(f"Could not read from file: {path}", format_io_error(e))
    chunks = []
    try:
        while True:
            try:
                data = os.read(fd, 65536)
            except OSError:
                break
            if not data:
                break
            chunks.append(data)
    finally:
        try:
            os.close(fd)
        except OSError:
            pass
    data = b"".join(chunks)
    lines = []
    pos = 0
    total = len(data)
    while pos < total:
        idx = data.find(b"\n", pos)
        if idx == -1:
            raw = data[pos:]
            nxt = total
            terminated = False
        else:
            raw = data[pos:idx]
            nxt = idx + 1
            terminated = True
        if terminated and raw.endswith(b"\r"):
            raw = raw[:-1]
        try:
            line = raw.decode("utf-8")
        except UnicodeDecodeError:
            break
        lines.append(line)
        pos = nxt
    return lines

def read_lines_or_empty(path):
    try:
        return read_lines(path)
    except BartibError:
        return []

def write_lines(path, lines):
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    except OSError as e:
        raise BartibError(f"Could not write to file: {path}", format_io_error(e))
    try:
        for line in lines:
            data = (line + "\n").encode("utf-8", "surrogateescape")
            while data:
                try:
                    written = os.write(fd, data)
                except OSError as e:
                    raise BartibError(f"Could not write to file: {path}", format_io_error(e))
                data = data[written:]
    finally:
        try:
            os.close(fd)
        except OSError:
            pass

def get_activities(path, print_warnings=True, emit_second_warning=True):
    lines = read_lines(path)
    activities = []
    for idx, line in enumerate(lines, start=1):
        try:
