    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
    except OSError as e:
        raise BartibError(f"Could not write to file: {path}", format_io_error(e))
    try:
        for line in lines:
            data = (line + "\n").encode("utf-8", "surrogateescape")
            while data:
                try:
                    written = os.write(fd, data)
                except OSError as e:
                    raise BartibError(f"Could not write to file: {path}", format_io_error(e))
                data = data[written:]
    finally:
        try:
            os.close(fd)
        except OSError:
            pass

def get_activities(path, print_warnings=True, emit_second_warning=True):
    lines = read_lines(path)
    activities = []
    for idx, line in enumerate(lines, start=1):
        try:
            act = parse_activity(line, idx, emit_second_warning)
        except ActivityParseError:
            if print_warnings:
                out_write(f"Warning: Ignoring line {idx}. Please see `bartib check` for further information\n")
            continue
        activities.append(act)
    return activities

