def parse_number_value(s):
    """Rust usize::from_str.  Returns int or None."""
    if s is None:
        return None
    t = s
    if t.startswith("+"):
        t = t[1:]
    if not t or not all(c in "0123456789" for c in t):
        return None
    val = int(t)
    if val > 18446744073709551615:
        return None
    return val

