    return val

def _is_char_boundary(data, idx):
    if idx <= 0 or idx >= len(data):
        return True
    return (data[idx] & 0xC0) != 0x80

def _char_at_byte(data, idx):
    # return (char, start, end) of the char covering byte idx
    pos = 0
    text = data.decode("utf-8", "surrogateescape")
    for ch in text:
        b_len = len(ch.encode("utf-8", "surrogateescape"))
        if pos <= idx < pos + b_len:
            return ch, pos, pos + b_len
        pos += b_len
    return "", pos, pos

