def _pad_nb(cell, width):
    return cell + NBSP * (width - len(cell))

def table_header_line(headers, widths):
    parts = []
    for i, h in enumerate(headers):
        parts.append(f"\x1b[4m{_pad_nb(h, widths[i])}\x1b[0m ")
    return "".join(parts) + "\n"

def table_row_line(cells, widths, color=None):
    parts = []
    for i, cell in enumerate(cells):
        padded = _pad_nb(cell, widths[i])
        if color is not None:
            parts.append(f"\x1b[{color}m{padded}\x1b[0m ")
        else:
            parts.append(padded + " ")
    return "".join(parts) + "\n"

def compute_widths(headers, rows):
    widths = [len(h) for h in headers]
    for row in rows:
        for i, cell in enumerate(row):
            if len(cell) > widths[i]:
                widths[i] = len(cell)
    return widths

def print_table(headers, rows, colors=None):
    if colors is None:
        colors = [None] * len(rows)
    widths = compute_widths(headers, rows)
    out_write("\n")
    out_write(table_header_line(headers, widths))
    for row, color in zip(rows, colors):
        out_write(table_row_line(row, widths, color))
    out_write("\n")

def bold(text):
    return f"\x1b[1m{text}\x1b[0m"

