def _full_usage(bin_name, spec_name):
    if spec_name == "__top__":
        return f"{bin_name} [OPTIONS] <SUBCOMMAND>"
    return f"{bin_name} {SPECS[spec_name]['full']}"

def _error_usage(bin_name, spec_name, used_ids, all_args_map, suggested_id=None):
    # trigger set: used ids plus (optionally) the suggested argument
    trigger = set(used_ids)
    if suggested_id is not None:
        trigger.add(suggested_id)
    required_ids = [a.id for a in all_args_map.values() if a.required]
    non_required_trigger = [i for i in trigger if i not in required_ids]
    if not non_required_trigger:
        return _full_usage(bin_name, spec_name)
    include = set(trigger) | set(required_ids)
    included_args = [all_args_map[i] for i in include if i in all_args_map]
