    if spec_name == "__top__":
        return f"{bin_name} {fragments}"
    return f"{bin_name} {spec_name} {fragments}"

def _clap_error_text(first_line, usage):
    return f"{first_line}\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n"

