_CONFLICT_WINNER_ORDER = ["from", "to", "date", "today", "yesterday", "current_week", "last_week"]

def _find_conflict(spec, present_ids):
    present = set(present_ids)
    arg_by_id = {a.id: a for a in spec["args"]}
    # subjects in winner order first, then any others in spec order
    ordered_subject_ids = [i for i in _CONFLICT_WINNER_ORDER if i in present]
    for a in spec["args"]:
        if a.id in present and a.id not in ordered_subject_ids:
            ordered_subject_ids.append(a.id)
    for sid in ordered_subject_ids:
        subj = arg_by_id.get(sid)
        if subj is None:
            continue
        partners = [pid for pid in subj.conflicts if pid in present]
        if not partners:
            continue
        # partner: earliest in winner order after the subject, else first
        partner_id = None
        if sid in _CONFLICT_WINNER_ORDER:
            after = _CONFLICT_WINNER_ORDER[_CONFLICT_WINNER_ORDER.index(sid) + 1:]
            for cand in after:
                if cand in partners:
                    partner_id = cand
                    break
        if partner_id is None:
            partner_id = partners[0]
        return subj, arg_by_id[partner_id]
    return None

